app.post('/api/bookings', requireLogin, async (req, res) => {
  const userId = req.session.userId;
  const { slotId } = req.body;
  const slot = await db.query('SELECT id, price FROM slots WHERE id = $1 AND seats_left > 0', [slotId]);
  if (!slot.rows.length) return res.status(409).json({ error: 'slot_unavailable' });
  const saved = await db.query(
    'INSERT INTO bookings (user_id, slot_id, amount) VALUES ($1, $2, $3) RETURNING id',
    [userId, slotId, slot.rows[0].price]
  );
  res.status(201).json({ id: saved.rows[0].id });
});

