app.post('/api/bookings', async (req, res) => {
  try {
    await db.query(
      'INSERT INTO bookings (slot_id, parent_id) VALUES ($1, $2)',
      [req.body.slotId, req.session.userId]
    );
    res.status(201).json({ ok: true, message: 'Booking confirmed' });
  } catch (err) {
    console.error('booking save failed', err.message);
    res.status(500).json({ ok: false, message: 'We could not save your booking. Please try again.' });
  }
});

